const cfg = $('⚙️ Config').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);
const row = rows.find(r => String(r.status || '').trim().toUpperCase() === 'READY');
if (!row) return [{ json: { ...cfg, topic_found: false, phase_status: 'NO_READY_TOPIC' } }];
const topic = String(row.title || row.topic || '').trim();
const seedKeyword = String(row.keyword || '').replace(/\s+/g, ' ').trim() || topic;
if (!topic) return [{ json: { ...cfg, ...row, topic_found: false, phase_status: 'INVALID_TOPIC' } }];
const site = String(row.site_url || '').replace(/\/+$/, '');
const autoPublish = String(row.auto_publish || '').toLowerCase() === 'yes' || row.auto_publish === true;
return [{ json: { ...cfg, ...row, topic_found: true, topic, title: topic, keyword: seedKeyword, site_url: site, target_country: row.target_country || cfg.default_target_country, location_code: Number(row.target_location_code || cfg.default_location_code), language: row.language || cfg.default_language, language_code: row.language_code || cfg.default_language_code, auto_publish_requested: autoPublish, existing_wp_post_id: row.wp_post_id || null, fact_repair_round: 0, qa_repair_round: 0, started_at: new Date().toISOString(), phase_status: 'TOPIC_SELECTED' } }];

const input = $input.first().json || {};
const maxKd = Number($("⚙️ Config").first().json.max_kd || 30);
const rows = Array.isArray(input.keywords) ? input.keywords : [];
const seen = new Set();
const keywords = rows.filter(row => { const keyword = String(row.keyword || '').trim(); const kdRaw = String(row.kd || ''); const kd = /\d/.test(kdRaw) ? Number(kdRaw.replace(/[^0-9.]/g, '')) : null; const key = keyword.toLowerCase(); if (!keyword || /[,@()]/.test(keyword) || (kd !== null && kd > maxKd) || seen.has(key)) return false; seen.add(key); return true; }).map(row => ({ ...row, keyword: String(row.keyword).trim(), kd: String(row.kd).trim() }));
const keywordSource = String(input.source || input.keyword_source || 'semrush').toLowerCase();
return [{ json: { ...input, count: keywords.length, keywords, keyword_source: keywordSource, phase_status: keywords.length ? keywordSource.toUpperCase() + '_KEYWORDS_READY' : keywordSource.toUpperCase() + '_NO_KEYWORDS' } }];

let parsed = $json.output;
if (typeof parsed === 'string') { const cleaned = parsed.replace(/```json|```/g, '').trim(); try { parsed = JSON.parse(cleaned); } catch (e) { return [{ json: { approved: false, reason: 'Invalid JSON from Gemini', raw: parsed } }]; } }
if (!parsed || typeof parsed !== 'object') return [{ json: { approved: false, reason: 'Gemini output is not an object', raw: $json } }];
const maxKdCfg = Number($("⚙️ Config").first().json.max_kd || 29);
const normalize = s => String(s || '').toLowerCase().replace(/[^\w\s]/g, '').replace(/\s+/g, ' ').trim();
const source = $('kd filter').first().json || {}; const sourceItems = Array.isArray(source.keywords) ? source.keywords : [];
const sourceName = String(source.keyword_source || source.source || 'semrush').toLowerCase();
if (!sourceItems.length) return [{ json: { approved: false, reason: sourceName + ' returned no usable keywords' } }];
const map = new Map(sourceItems.map(k => [normalize(k.keyword), k])); const primary = map.get(normalize(parsed.primary_keyword));
if (!primary || Number(primary.kd) > maxKdCfg) return [{ json: { approved: false, reason: 'Primary keyword is not a valid ' + sourceName + ' keyword', parsed } }];
const secondary = []; const used = new Set([normalize(primary.keyword)]);
for (const item of (Array.isArray(parsed.secondary_keywords) ? parsed.secondary_keywords : [])) { const k = map.get(normalize(typeof item === 'string' ? item : item.keyword)); if (k && (!/\d/.test(String(k.kd || '')) || Number(k.kd) <= maxKdCfg) && !used.has(normalize(k.keyword))) { used.add(normalize(k.keyword)); secondary.push({ keyword: k.keyword, volume: k.volume || '', kd: k.kd || '' }); } if (secondary.length >= 20) break; }
const lsi = [...new Set((Array.isArray(parsed.lsi_keywords) ? parsed.lsi_keywords : []).map(x => String(x).trim()).filter(Boolean))].slice(0, 12);
const minSecondary = Number($("⚙️ Config").first().json.min_secondary_keywords || 15); if (secondary.length < minSecondary) return [{ json: { approved: false, reason: 'Fewer than ' + minSecondary + ' secondary keywords', available_secondary: secondary.length, parsed } }];
return [{ json: { approved: true, primary_keyword: primary.keyword, primary_volume: primary.volume || '', primary_kd: primary.kd || '', secondary_keywords: secondary, lsi_keywords: lsi, niche: ($('♻️ Restore Context').first().json.niche || 'auto'), keyword_source: sourceName, reasoning: parsed.reasoning || '', niche_alignment: parsed.niche_alignment || '', phase_status: 'KEYWORD_APPROVED' } }];

const ctx = $json;
const serp = ctx.serp || {};
const resultsFound = Number(serp.resultsFound || 0);
const containerFound = Boolean(serp.containerFound);
if (!containerFound || resultsFound < 3) { throw new Error(`SERP scraping failed: containerFound=${containerFound} resultsFound=${resultsFound}.`); }
return [{ json: ctx }];

const raw = $json || {};
let baseCtx = {};
try { baseCtx = $('♻️ Restore Context').first().json || {}; } catch (e) { try { baseCtx = $('🎯 Select READY Topic').first().json || {}; } catch (e2) {} }
let keyword = '';
if (!keyword) { try { const approved = $('Parse & Validate JSON').first().json; if (approved && approved.approved) keyword = String(approved.primary_keyword || '').trim(); } catch (e) {} }
if (!keyword) { try { const gemini = $('📥 Parse Gemini Fallback').first().json; if (gemini && gemini.keyword_status === 'Approved') { keyword = String(gemini.keyword || gemini.primary_keyword || '').trim(); } } catch (e) {} }
if (!keyword) keyword = String(baseCtx.keyword || baseCtx.primary_keyword || '').trim();
if (!keyword && raw.keyword) keyword = String(raw.keyword).trim();
let primaryVolume = '';
let primaryKd = '';
let secondaryKeywords = [];
let lsiKeywords = [];
try { const approved = $('Parse & Validate JSON').first().json; if (approved && approved.approved) { primaryVolume = approved.primary_volume || ''; primaryKd = approved.primary_kd || ''; secondaryKeywords = approved.secondary_keywords || []; lsiKeywords = approved.lsi_keywords || []; } } catch (e) {}
if (!primaryVolume) { try { const gemini = $('📥 Parse Gemini Fallback').first().json; if (gemini && gemini.keyword_status === 'Approved') { secondaryKeywords = gemini.secondary_keywords || []; } } catch (e) {} }
const serp = raw.serp || raw;
const results = serp.results || serp.items || [];
const competitors = results.filter(c => c && c.url).slice(0, 10).map((c, i) => {
  let domain = c.domain || '';
  if (!domain && c.url) { try { domain = new URL(c.url).hostname.replace(/^www\./, ''); } catch (e) { domain = ''; } }
  return { position: c.position || i + 1, domain, url: c.url, title: c.title || '', description: c.description || c.snippet || '', pageAS: c.pageAS || c.page_as || 0, refDomains: c.refDomains || c.ref_domains || 0, backlinks: c.backlinks || 0, traffic: c.traffic || 0, urlKeywords: c.keywords || c.urlKeywords || 0 };
});
return [{ json: { ...baseCtx, keyword, primary_keyword: keyword, primary_volume: primaryVolume || baseCtx.primary_volume || '', primary_kd: primaryKd || baseCtx.primary_kd || '', lsi_keywords: lsiKeywords.length ? lsiKeywords : (baseCtx.lsi_keywords || []), secondary_keywords: secondaryKeywords.length ? secondaryKeywords : (baseCtx.secondary_keywords || []), serp_competitors: competitors, competitor_count: competitors.length, phase_status: 'SERP_READY' } }];

const items = $input.all();
const split = $('🔀 Split Competitors').all();
function stripTags(html) { return String(html || '').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/\s+/g, ' ').trim(); }
return items.map((item, index) => {
  const meta = split[index]?.json || {};
  const j = item.json || {};
  const html = typeof j === 'string' ? j : (j.data || j.html || j.body || '');
  const usable = String(html).length > 500 && /<html|<body|<title|<h1/i.test(html);
  const titleMatch = String(html).match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  const metaDescMatch = String(html).match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i);
  const h1 = [...String(html).matchAll(/<h1\b[^>]*>([\s\S]*?)<\/h1>/gi)].map(m => stripTags(m[1])).filter(Boolean);
  const h2 = [...String(html).matchAll(/<h2\b[^>]*>([\s\S]*?)<\/h2>/gi)].map(m => stripTags(m[1])).filter(Boolean);
  const h3 = [...String(html).matchAll(/<h3\b[^>]*>([\s\S]*?)<\/h3>/gi)].map(m => stripTags(m[1])).filter(Boolean);
  let mainHtml = (String(html).match(/<main\b[^>]*>([\s\S]*?)<\/main>/i) || [])[1] || (String(html).match(/<article\b[^>]*>([\s\S]*?)<\/article>/i) || [])[1] || html;
  const mainText = stripTags(mainHtml);
  const wordCount = mainText.split(/\s+/).filter(Boolean).length;
  return { json: { competitorIndex: index + 1, keyword: meta.keyword || '', position: meta.position ?? null, domain: meta.domain || '', url: meta.url || meta._competitor_url || '', pageAS: meta.pageAS || 0, refDomains: meta.refDomains || 0, backlinks: meta.backlinks || 0, traffic: meta.traffic || 0, urlKeywords: meta.urlKeywords || 0, fetchStatus: usable ? 'ok' : 'blocked', usable, seo: { title: titleMatch ? stripTags(titleMatch[1]) : '', titleLength: titleMatch ? stripTags(titleMatch[1]).length : 0, metaDescription: metaDescMatch ? stripTags(metaDescMatch[1]) : '', metaDescriptionLength: metaDescMatch ? stripTags(metaDescMatch[1]).length : 0, h1, h2, h3, h1Count: h1.length, h2Count: h2.length, h3Count: h3.length, wordCount }, extractedText: mainText.slice(0, 20000) } };
});

const items = $input.all();
const usable = items.filter(i => i.json.usable);
const all = items.map(i => i.json);
const stats = usable.length ? usable : items;
const wordCounts = stats.map(i => i.json.seo?.wordCount || 0).filter(n => n > 0);
const avgWords = wordCounts.length ? Math.round(wordCounts.reduce((a,b) => a+b, 0) / wordCounts.length) : 1500;
const allH2 = []; const allH3 = [];
for (const it of stats) { allH2.push(...(it.json.seo?.h2 || [])); allH3.push(...(it.json.seo?.h3 || [])); }
const freq = (arr) => {
  const m = new Map();
  for (const x of arr) { const k = String(x || '').toLowerCase().trim(); if (!k) continue; m.set(k, (m.get(k) || 0) + 1); }
  return [...m.entries()].sort((a,b) => b[1] - a[1]).slice(0, 30).map(([topic, count]) => ({ topic, count }));
};
const ctx = $('🎯 Prep SERP Competitors').first().json;
return [{ json: { ...ctx, competitor_stats: { total: all.length, usable: usable.length, avg_word_count: avgWords, min_word_count: wordCounts.length ? Math.min(...wordCounts) : 0, max_word_count: wordCounts.length ? Math.max(...wordCounts) : 0 }, common_h2: freq(allH2), common_h3: freq(allH3), competitors: all, phase_status: 'COMPETITORS_ANALYZED' } }];

const ctx = $json;
const site_url = String(ctx.site_url || '').replace(/\/+$/, '');
const topic_id = ctx.topic_id || '';
const kw = String(ctx.keyword || ctx.primary_keyword || '').trim();
if (!site_url) throw new Error('site_url missing');
if (!kw) throw new Error('keyword missing');
// real search questions from the Ahrefs list (they have search demand): the best FAQ material
const qRe = /^(what|how|why|when|where|who|which|is|are|can|does|do|did|will|should)\b/i;
const question_keywords = (Array.isArray(ctx.secondary_keywords) ? ctx.secondary_keywords : []).map(k => typeof k === 'string' ? k : k.keyword).filter(k => k && qRe.test(k)).slice(0, 12);
return [{ json: { ...ctx, site_url, topic_id, keyword: kw, primary_keyword: kw, question_keywords, phase_status: 'READY_FOR_GEMINI_FAQ' } }];

parameters.text:
=You are a senior SEO editor writing the FAQ section of a blog post. Write FAQs that real searchers ask and that can win a Google FAQ rich result.

FOCUS KEYWORD: {{ $json.keyword }}
BLOG TITLE: {{ $json.title }}
SEARCH INTENT: {{ $json.search_intent || 'informational' }}

REAL SEARCH QUESTIONS from Ahrefs (they have real search demand, prefer them):
{{ JSON.stringify($json.question_keywords || [], null, 2) }}

RESEARCH (the ONLY source of facts and numbers for your answers):
{{ JSON.stringify((($('📊 Analyze SERP').first().json.competitors) || []).filter(c => c.usable).slice(0, 4).map(c => ({ domain: c.domain, text: String(c.extractedText || '').replace(/\s+/g, ' ').slice(0, 3500) })), null, 2) }}

COMPETITOR H2s (what readers care about):
{{ JSON.stringify(($json.common_h2 || []).slice(0, 10).map(x => x.topic), null, 2) }}

TASK: write exactly {{ Number($('⚙️ Config').first().json.faq_count || 6) + 1 }} FAQs (the best {{ $('⚙️ Config').first().json.faq_count || 6 }} are kept). In at least two answers use the exact FOCUS KEYWORD naturally.

QUALITY RULES (checked by code afterwards):
1. Choose the questions readers most want answered. Use the REAL SEARCH QUESTIONS first (rewrite each into a clean, natural question) and fill the remaining slots from the research and the competitor headings. No two questions may ask for the same fact.
2. Every question ends with "?", has 5-14 words, and uses natural wording. No more than TWO questions may start with the same first word, so vary What / How / Why / When / Is / Does / Can.
3. Every answer has 35-65 words in 2-3 short sentences. The FIRST sentence answers the question directly (a snippet Google can show) and repeats the key term of the question. The next sentence adds one supporting fact: a date, number or name from the RESEARCH.
4. Facts: every number, date, name and amount comes from the RESEARCH above, copied exactly (write money as $40 million). If the research does not support an answer, replace that question with another one. Never guess, never write "unknown", never invent.
5. Active voice and plain words. Use a transition word (also, however, because, for example, so) where it sounds natural. No marketing talk, no filler such as "It is important to note" or "In today's world".
6. Never use em or en dashes. The answers must agree with each other and with the facts in the research.

OUTPUT: return ONLY this JSON (no markdown):
{
  "faqs": [
    { "question": "What is ...?", "answer": "..." }
  ]
}

parameters.jsCode:
const ctx = $('🧩 Prep Gemini FAQ').first().json;
const raw = $json || {};

let text = '';
if (typeof raw.text === 'string') text = raw.text;
else if (typeof raw.output === 'string') text = raw.output;
else if (raw.output && typeof raw.output === 'object') {
  const obj = raw.output;
  const faqs = Array.isArray(obj.faqs) ? obj.faqs : [];
  return [{ json: { ...ctx, reddit_faqs: faqs.map((f, i) => ({ order: i + 1, question: String(f.question || '').trim(), answer: String(f.answer || '').trim(), source: 'gemini', source_url: '' })).filter(f => f.question && f.answer), faq_source: 'gemini', phase_status: 'GEMINI_FAQS_READY' } }];
}

if (!text) return [{ json: { ...ctx, reddit_faqs: [], faq_source: 'gemini_failed', faq_error: 'no text output', phase_status: 'GEMINI_FAQS_EMPTY' } }];

text = String(text).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();

let parsed = null;
try { parsed = JSON.parse(text); }
catch (e) {
  const a = text.indexOf('{'); const b = text.lastIndexOf('}');
  if (a >= 0 && b > a) { try { parsed = JSON.parse(text.slice(a, b + 1)); } catch (e2) {} }
}

if (!parsed || !Array.isArray(parsed.faqs)) {
  return [{ json: { ...ctx, reddit_faqs: [], faq_source: 'gemini_failed', faq_error: 'invalid JSON', raw: text.slice(0, 500), phase_status: 'GEMINI_FAQS_EMPTY' } }];
}

const fillerRe = /common question about|see the related discussion|as an ai|i cannot|it is important to note/i;
const seenQ = new Set();
const faqs = parsed.faqs.map(f => ({
  question: String(f.question || '').replace(/\s+/g, ' ').trim().replace(/[?\uFF1F]*$/, '?'),
  answer: String(f.answer || '').replace(/\s+/g, ' ').replace(/\s*[\u2013\u2014]\s*/g, ', ').trim()
})).filter(f => f.question.length > 8 && f.answer)
  .filter(f => { const n = f.answer.split(' ').length; return n >= 25 && n <= 90 && !fillerRe.test(f.answer); })
  .filter(f => { const k = f.question.toLowerCase().replace(/[^a-z0-9 ]/g, ''); if (seenQ.has(k)) return false; seenQ.add(k); return true; })
  .map((f, i) => ({ order: i + 1, question: f.question, answer: f.answer, source: 'gemini', source_url: '' }));

return [{ json: { ...ctx, reddit_faqs: faqs, reddit_faq_count: faqs.length, faq_source: 'gemini', phase_status: faqs.length ? 'GEMINI_FAQS_READY' : 'GEMINI_FAQS_EMPTY' } }];

const ctx = $json;
const saved = $('♻️ Restore Context').first().json;
const site_url = String(ctx.site_url || saved.site_url || '').replace(/\/+$/, '');
const topic_id = ctx.topic_id || saved.topic_id || '';
const kw = String(ctx.keyword || saved.keyword || saved.primary_keyword || '').trim();
if (!site_url) throw new Error('site_url missing');
if (!kw) throw new Error('keyword missing');
const geminiFaqs = Array.isArray(ctx.reddit_faqs) ? ctx.reddit_faqs : [];
let faqPlan = geminiFaqs.map(f => f.question);
const fallback = [`What is ${kw}?`, `Why is ${kw} important?`, `How does ${kw} work?`, `What are common mistakes with ${kw}?`, `How do you get started with ${kw}?`, `What results can you expect from ${kw}?`];
for (const f of fallback) {
  if (faqPlan.length >= 6) break;
  if (!faqPlan.includes(f)) faqPlan.push(f);
}
return [{ json: { ...ctx, site_url, topic_id, keyword: kw, primary_keyword: kw, faq_plan: faqPlan.slice(0, 6), faq_source: geminiFaqs.length ? 'gemini' : 'fallback_template', phase_status: 'FAQ_PLAN_READY' } }];

// Internal links (point 10): pick related posts, spread over DIFFERENT categories when possible
const ctx = $('🧩 Build FAQ Plan').first().json;
const STOP = new Set(['the', 'and', 'for', 'with', 'from', 'what', 'how', 'why', 'who', 'when', 'where', 'which', 'your', 'you', 'are', 'was', 'were', 'this', 'that', 'into', 'about', 'more', 'best', 'top', '2024', '2025', '2026', '2027']);
const toks = s => String(s || '').toLowerCase().replace(/['’]s\b/g, '').split(/[^a-z0-9]+/).filter(w => w.length > 2 && !STOP.has(w));
const kwWords = [...new Set(toks(ctx.keyword))];
const secWords = (Array.isArray(ctx.secondary_keywords) ? ctx.secondary_keywords : []).slice(0, 12).flatMap(k => toks(typeof k === 'string' ? k : k.keyword));
const lsiWords = (Array.isArray(ctx.lsi_keywords) ? ctx.lsi_keywords : []).flatMap(k => toks(typeof k === 'string' ? k : k.keyword));
const topicWords = new Set([...kwWords, ...toks(ctx.title), ...secWords, ...lsiWords]);
const GENERIC = new Set(['work', 'tips', 'guide', 'ideas', 'review', 'online', 'free', 'business', 'list', 'world', 'life']);
const pages = $input.all().map(i => i.json).filter(p => p && p.id && p.link);

const allScored = pages.map(p => {
  const title = String(p.title?.rendered || p.title || '');
  const pageWords = new Set(toks(title + ' ' + (p.slug || '')));
  const overlapPrimary = kwWords.filter(w => pageWords.has(w)).length;
  const sharedTopic = [...pageWords].filter(w => topicWords.has(w));
  const overlapTopic = sharedTopic.length;
  // one shared word is enough when it is a real topic word (not a generic one like 'work' or 'tips')
  const strongSingle = overlapTopic === 1 && sharedTopic[0].length >= 5 && !GENERIC.has(sharedTopic[0]);
  const primaryRatio = overlapPrimary / Math.max(kwWords.length, 1);
  const terms = Array.isArray(p._embedded?.['wp:term']) ? (p._embedded['wp:term'][0] || []) : [];
  const category = (terms[0] && (terms[0].name || terms[0].slug)) || (Array.isArray(p.categories) && p.categories[0] != null ? 'cat-' + p.categories[0] : 'uncategorized');
  return {
    id: p.id, url: p.link, title: title.replace(/<[^>]+>/g, '').replace(/&#8217;/g, "'").replace(/&amp;/g, '&'), slug: p.slug || '', category,
    relevance: Math.max(primaryRatio, Math.min(1, overlapTopic / 4), strongSingle ? 0.25 : 0), eligible: primaryRatio >= 0.5 || overlapTopic >= 2 || strongSingle
  };
}).sort((a, b) => b.relevance - a.relevance);
const scored = allScored.filter(p => p.eligible);

// pass 1: the best post of each different category; pass 2: fill with the next best
const picked = [];
const usedCats = new Set();
for (const p of scored) { if (picked.length >= 5) break; if (!usedCats.has(p.category)) { picked.push(p); usedCats.add(p.category); } }
for (const p of scored) { if (picked.length >= 5) break; if (!picked.includes(p)) picked.push(p); }

// fallback: a new blog has few related posts. SEO plugins still want internal links, so fill up to 2 with the most relevant remaining posts (different categories first)
const MIN_LINKS = 2;
if (picked.length < MIN_LINKS) {
  const rest = allScored.filter(p => !picked.includes(p));
  for (const p of rest) { if (picked.length >= MIN_LINKS) break; if (!usedCats.has(p.category)) { picked.push(p); usedCats.add(p.category); } }
  for (const p of rest) { if (picked.length >= MIN_LINKS) break; if (!picked.includes(p)) picked.push(p); }
}

// last resort: a new blog may have no published posts yet. The home page is always live and counts as an internal link for Rank Math.
if (picked.length === 0 && ctx.site_url) {
  const base = String(ctx.site_url).replace(/\/+$/, '');
  const host = base.replace(/^https?:\/\//, '').replace(/^www\./, '');
  picked.push({ id: 0, url: base + '/', title: 'more guides on ' + host, slug: '', category: 'home', relevance: 0, eligible: true });
}
return [{ json: { ...ctx, internal_link_candidates: picked, internal_link_categories: [...usedCats], existing_slugs: pages.map(p => p.slug).filter(Boolean), wp_posts_found: pages.length, phase_status: 'INTERNAL_LINKS_READY' } }];

// External links (point 13): trusted pages that match the article topic, never social media or the own site
const ctx = $json;
const competitors = (ctx.competitors || []).filter(c => c.usable && c.url);
const hostOf = u => String(u || '').replace(/^https?:\/\//i, '').split(/[\/?#]/)[0].replace(/^www\./i, '').toLowerCase();
const siteHost = hostOf(ctx.site_url);
const STOP = new Set(['the', 'and', 'for', 'with', 'from', 'what', 'how', 'why', 'who', 'when', 'where', 'which', 'your', 'you', 'are', 'was', 'were', 'this', 'that', 'into', 'about', 'more', 'best', 'top', '2024', '2025', '2026', '2027']);
const toks = s => String(s || '').toLowerCase().replace(/['’]s\b/g, '').split(/[^a-z0-9]+/).filter(w => w.length > 2 && !STOP.has(w));
const topicWords = new Set([...toks(ctx.keyword), ...toks(ctx.title), ...(Array.isArray(ctx.secondary_keywords) ? ctx.secondary_keywords : []).slice(0, 8).flatMap(k => toks(typeof k === 'string' ? k : k.keyword))]);
const SOCIAL = ['instagram.com', 'tiktok.com', 'youtube.com', 'youtu.be', 'facebook.com', 'x.com', 'twitter.com', 'reddit.com', 'pinterest.com', 'quora.com', 'linkedin.com', 'medium.com', 'blogspot.com', 'wordpress.com', 'tumblr.com', 'google.com', 'bing.com', 'amazon.com', 'ebay.com'];
const AUTH = ['wikipedia.org', 'britannica.com', 'forbes.com', 'imdb.com', 'biography.com', 'reuters.com', 'apnews.com', 'bbc.com', 'bbc.co.uk', 'nytimes.com', 'theguardian.com', 'washingtonpost.com', 'bloomberg.com', 'cnbc.com', 'techcrunch.com', 'theverge.com', 'wired.com', 'statista.com', 'hbr.org', 'nature.com', 'sciencedirect.com', 'who.int', 'nih.gov', 'cdc.gov', 'mozilla.org', 'ahrefs.com', 'semrush.com', 'moz.com', 'searchenginejournal.com', 'searchengineland.com', 'hubspot.com', 'developers.google.com', 'support.google.com', 'cloudflare.com', 'wordpress.org', 'github.com'];
